1: import { Injectable } from '@angular/core';
2: import { ActivatedRouteSnapshot, CanActivate, RouterStateSnapshot } from '@angular/router';
3: import { TranslateService } from '@ngx-translate/core';
4: import { PopUpManager } from 'src/app/managers/popup_manager';
5: 
6: @Injectable({
7:   providedIn: 'root',
8: })
9: export class AuthGuard implements CanActivate {
10: 
11:   constructor(
12:     private popUpManager: PopUpManager,
13:     private translate: TranslateService,
14:   ) {}
15: 
16:   canActivate(route: ActivatedRouteSnapshot, state: RouterStateSnapshot) {
17:     const menuInfo = localStorage.getItem('menu');
18:     const menuPermisos = menuInfo ? JSON.parse(atob(menuInfo)) : null;
19:     const fullUrl = window.location.href;
20:     const url = new URL(fullUrl);
21:     const path = url.pathname;
22: 
23:     // Obtener parámetros de la ruta
24:     const params = route.params;
25: 
26:     if (menuPermisos != null) {
27:       // Pasar tanto la URL como los parámetros a la función de verificación
28:       if (checkUrlExists(menuPermisos, path, params)) {
29:         return true;
30:       }
31:     }
32: 
33:     this.popUpManager.showErrorAlert(this.translate.instant('ERROR.rol_insuficiente_titulo'));
34:     return false;
35:   }
36: 
37:   canActivateChild(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): boolean {
38:     return this.canActivate(route, state);
39:   }
40: }
41: 
42: // Recorrer el menú para verificar si la URL y los parámetros existen
43: function checkUrlExists(menuItems: any, targetUrl: string, params: any) {
44:   return menuItems.some((item: any) => {
45:     // Verificar la URL y los parámetros
46:     if (item.Url === targetUrl && checkParams(item.Params, params)) {
47:       return true;
48:     }
49:     if (item.Opciones && item.Opciones.length > 0) {
50:       return checkUrlExists(item.Opciones, targetUrl, params);
51:     }
52:     return false;
53:   });
54: }
55: 
56: // Verificar los parámetros de la ruta
57: function checkParams(expectedParams: any, actualParams: any): boolean {
58:   if (!expectedParams) {
59:     return true; // No se requieren parámetros específicos
60:   }
61:   for (let key in expectedParams) {
62:     if (expectedParams[key] !== actualParams[key]) {
63:       return false; // Un parámetro no coincide
64:     }
65:   }
66:   return true; // Todos los parámetros coinciden
67: }

